// Offline support for the web version. VERSION and FILES are generated by scripts/build-sw.js.
const VERSION = '1e66dac232cc';
const FILES = ["./","app.js","cards/hearts.js","cards/logic.js","cards/ui.js","engine.js","guides.js","i18n.js","icons/icon-180.png","icons/icon-192.png","icons/icon-512.png","index.html","manifest-fr.webmanifest","manifest.webmanifest","style.css"];

self.addEventListener('install', e => {
  // A new version is downloaded whole before it replaces the old one.
  e.waitUntil(caches.open(VERSION)
    .then(c => c.addAll(FILES.map(f => new Request(f, { cache: 'reload' }))))
    .then(() => self.skipWaiting()));
});

self.addEventListener('activate', e => {
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => k !== VERSION).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});

self.addEventListener('fetch', e => {
  if (e.request.method !== 'GET') return;
  const target = e.request.mode === 'navigate' ? './' : e.request;
  e.respondWith(caches.open(VERSION).then(c => c.match(target)).then(hit => hit || fetch(e.request)));
});
